changeSet.sql:

ALTER TABLE gps_track_data_points
    ALTER COLUMN elevation_loss_per_hour_moving_window TYPE numeric(12,2) USING round(elevation_loss_per_hour_moving_window::numeric, 2),
    ALTER COLUMN energy_gravitational_wh TYPE numeric(22,10) USING round(energy_gravitational_wh::numeric, 10),
    ALTER COLUMN energy_aero_drag_wh TYPE numeric(22,10) USING round(energy_aero_drag_wh::numeric, 10),
    ALTER COLUMN energy_rolling_resistance_wh TYPE numeric(22,10) USING round(energy_rolling_resistance_wh::numeric, 10),
    ALTER COLUMN energy_kinetic_wh TYPE numeric(22,10) USING round(energy_kinetic_wh::numeric, 10),
    ALTER COLUMN energy_total_wh TYPE numeric(22,10) USING round(energy_total_wh::numeric, 10),
    ALTER COLUMN energy_cumulative_wh TYPE numeric(22,10) USING round(energy_cumulative_wh::numeric, 10),
    ALTER COLUMN power_watts TYPE numeric(12,2) USING round(power_watts::numeric, 2);

COMMENT ON COLUMN gps_track_data_points.energy_gravitational_wh IS
    'Per-point energy component in Wh, stored at numeric(22,10) intentionally. Individual GPS segments can be far below 0.01 Wh, and rounding them too early would drift summed track totals; UI and track totals round separately.';
COMMENT ON COLUMN gps_track_data_points.energy_aero_drag_wh IS
    'Per-point energy component in Wh, stored at numeric(22,10) intentionally. Individual GPS segments can be far below 0.01 Wh, and rounding them too early would drift summed track totals; UI and track totals round separately.';
COMMENT ON COLUMN gps_track_data_points.energy_rolling_resistance_wh IS
    'Per-point energy component in Wh, stored at numeric(22,10) intentionally. Individual GPS segments can be far below 0.01 Wh, and rounding them too early would drift summed track totals; UI and track totals round separately.';
COMMENT ON COLUMN gps_track_data_points.energy_kinetic_wh IS
    'Per-point energy component in Wh, stored at numeric(22,10) intentionally. Individual GPS segments can be far below 0.01 Wh, and rounding them too early would drift summed track totals; UI and track totals round separately.';
COMMENT ON COLUMN gps_track_data_points.energy_total_wh IS
    'Per-point total energy in Wh, stored at numeric(22,10) intentionally. Individual GPS segments can be far below 0.01 Wh, and rounding them too early would drift summed track totals; UI and track totals round separately.';
COMMENT ON COLUMN gps_track_data_points.energy_cumulative_wh IS
    'Per-point cumulative energy in Wh, stored at numeric(22,10) to preserve the high-scale sum of tiny segment values; response and UI layers round separately.';


ALTER TABLE gps_track_event
    ALTER COLUMN confidence TYPE numeric(5,2) USING round(confidence::numeric, 2);

ALTER TABLE web_client_environment_log
    ALTER COLUMN device_pixel_ratio TYPE numeric(4,2) USING round(device_pixel_ratio::numeric, 2),
    ALTER COLUMN device_memory_gb TYPE numeric(6,2) USING round(device_memory_gb::numeric, 2);
